  --transition: 150ms ease;
}

/* ── Skip link ──────────────────────────────────────────────── */
.skip-link {
  position: absolute;
  top: -100%;
  left: 1rem;
  padding: .5rem 1rem;
  background: var(--color-primary);
  color: #fff;
  border-radius: var(--radius-sm);
  font: 600 .875rem/1 var(--font);
  text-decoration: none;
  z-index: 999;
  transition: top var(--transition);
}
.skip-link:focus { top: 1rem; }

