  flex-shrink: 0;
}

.page-header__icon svg { color: #fff; }

.page-header__title {
  font-size: 1rem;
  font-weight: 700;
  letter-spacing: -.01em;
  color: var(--color-text);
}

main {
  max-width: 680px;
  margin: 0 auto;
  padding: 2.5rem 1.25rem 4rem;
}

/* ── Quiz heading block ─────────────────────────────────────── */
.quiz-heading {
  margin-bottom: 2rem;
}

.quiz-heading h1 {
  font-size: clamp(1.5rem, 4vw, 2rem);
  font-weight: 800;
  letter-spacing: -.03em;
  line-height: 1.2;
  color: var(--color-text);
  margin-bottom: .5rem;
}

.quiz-heading__sub {
  font-size: .9375rem;
  color: var(--color-text-muted);
}

/* ── Progress bar ───────────────────────────────────────────── */
.quiz-progress {
  margin-bottom: 2rem;
}

.quiz-progress__label {
  font-size: .8125rem;
  font-weight: 600;
  color: var(--color-text-muted);
  margin-bottom: .4rem;
  display: flex;
  justify-content: space-between;
}

.quiz-progress__bar {
  height: 6px;
  background: var(--color-border);
  border-radius: 999px;
  overflow: hidden;
}

.quiz-progress__fill {
  height: 100%;
  width: var(--progress, 0%);
  background: var(--color-primary);
  border-radius: 999px;
  transition: width .4s ease;
}

/* ── Form ───────────────────────────────────────────────────── */
.quiz-form {
  display: flex;
  flex-direction: column;
  gap: 1.25rem;
}

/* ── Question card (form-field) ─────────────────────────────── */
.form-field {
  background: var(--color-surface);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-lg);
  box-shadow: var(--shadow-card);
  padding: 1.5rem;
}

.form-field fieldset {
  border: none;
  padding: 0;
  min-width: 0;
}

.form-field .question-header {
  display: flex;
  align-items: flex-start;
  gap: .75rem;
  margin-bottom: 1rem;
}

.form-field .question-num {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-width: 28px;
  height: 28px;
  background: var(--color-primary);
  color: #fff;
  font-size: .75rem;
  font-weight: 700;
  border-radius: 50%;
  flex-shrink: 0;
  margin-top: .1rem;
}

.form-field legend {
  font-size: 1rem;
  font-weight: 700;
  color: var(--color-text);
  line-height: 1.4;
  /* legend + span layout handled by the question-header flex */
  padding: 0;
  float: left; /* allow sibling elements inside fieldset to wrap around */
  width: 100%;
}

/* Clear float for fieldset content */
.form-field .legend-wrap::after {
  content: "";
  display: table;
  clear: both;
}

/* ── Help text ──────────────────────────────────────────────── */
.help-text {
  font-size: .8125rem;
  color: var(--color-help);
  background: #f9fafb;
  border: 1px solid var(--color-border);
  border-radius: var(--radius-sm);
  padding: .5rem .75rem;
  margin-bottom: 1rem;
  line-height: 1.5;
}

.help-text svg {
  display: inline;
  vertical-align: middle;
  margin-right: .3rem;
  flex-shrink: 0;
}

/* ── Options list ───────────────────────────────────────────── */
.options-list {
  display: flex;
  flex-direction: column;
  gap: .5rem;
  list-style: none;
}

/* ── Checkbox option ────────────────────────────────────────── */
.option {
  display: flex;
  align-items: center;
  gap: .75rem;
  padding: .75rem 1rem;
  border: 1.5px solid var(--color-border);
  border-radius: var(--radius-md);
  cursor: pointer;
  transition: border-color var(--transition), background var(--transition);
  user-select: none;
}

.option:hover {
  border-color: var(--color-primary);
  background: #f8faff;
}

.option input[type="checkbox"] {
  width: 18px;
  height: 18px;
  flex-shrink: 0;
  accent-color: var(--color-primary);
  cursor: pointer;
}

/* Highlight checked options */
.option:has(input:checked) {
  border-color: var(--color-primary);
  background: var(--color-checked-bg);
}

.option__label {
  font-size: .9375rem;
  color: var(--color-text);
  cursor: pointer;
  line-height: 1.4;
}

/* ── Error message ──────────────────────────────────────────── */
.error-text {
  font-size: .8125rem;
  color: var(--color-error);
  font-weight: 600;
  margin-top: .75rem;
  display: none;
}

.error-text[aria-hidden="false"] { display: block; }

/* ── Submit section ─────────────────────────────────────────── */
.quiz-footer {
  margin-top: .5rem;
  display: flex;
  flex-direction: column;
  align-items: flex-end;
  gap: .75rem;
}

.btn-submit {
  display: inline-flex;
  align-items: center;
  gap: .5rem;
  padding: .8125rem 1.75rem;
  background: var(--color-primary);
  color: #fff;
  font: 600 1rem/1 var(--font);
  border: none;
  border-radius: var(--radius-md);
  cursor: pointer;
  transition: background var(--transition), transform var(--transition), box-shadow var(--transition);
  box-shadow: 0 1px 2px rgba(0,0,0,.12), 0 2px 8px rgba(37,99,235,.25);
}

.btn-submit:hover {
  background: var(--color-primary-dark);
  transform: translateY(-1px);
  box-shadow: 0 2px 4px rgba(0,0,0,.14), 0 4px 14px rgba(37,99,235,.35);
}

.btn-submit:active { transform: translateY(0); }

.btn-submit:focus-visible {
  outline: 3px solid var(--color-border-focus);
  outline-offset: 2px;
}

/* ── Status / result ────────────────────────────────────────── */
#quiz-status {
  font-size: .875rem;
  color: var(--color-text-muted);
}

.result-card {
  background: var(--color-success-bg);
  border: 1px solid var(--color-success-bdr);
  border-radius: var(--radius-lg);
  padding: 1.5rem;
  text-align: center;
}

.result-card__score {
  font-size: 2.5rem;
  font-weight: 800;
  color: var(--color-success-text);
  letter-spacing: -.04em;
  line-height: 1;
}

.result-card__label {
  font-size: .9375rem;
  color: var(--color-success-text);
  margin-top: .4rem;
}

.result-card__detail {
  font-size: .875rem;
  color: var(--color-help);
  margin-top: .75rem;
  line-height: 1.5;
}

/* ── Focus styles ───────────────────────────────────────────── */
:focus-visible {
  outline: 3px solid var(--color-border-focus);
  outline-offset: 2px;
  border-radius: 2px;
}

/* ── Reduced motion ─────────────────────────────────────────── */
@media (prefers-reduced-motion: reduce) {
  *, .btn-submit, .quiz-progress__fill { transition: none !important; }
}

/* ── Forced colors (high-contrast) ─────────────────────────── */
@media (forced-colors: active) {
  .form-field  { border: 2px solid ButtonText; }
  .option      { border: 2px solid ButtonText; }
  .btn-submit  { border: 2px solid ButtonText; forced-color-adjust: auto; }
  .help-text   { border: 1px solid ButtonText; }
}

/* ── Narrow viewport / reflow ───────────────────────────────── */
@media (max-width: 480px) {
  main { padding: 1.5rem 1rem 3rem; }
  .form-field { padding: 1.25rem 1rem; }
  .quiz-heading h1 { font-size: 1.4rem; }
}
